@CrossOrigin
@RestController
@RequestMapping("/CategoryQuery")
public class CategoryQueryRestController extends BaseSpringRestController {
	
	public CategoryQueryRestController( CategoryService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Category using a UUID
     * @param		UUID categoryId
     * @return		Category
     */    
    @GetMapping("/load")
    public Category load( @RequestParam(required=true) UUID categoryId ) {
    	Category entity = null;

    	try {  
    		entity = service.getCategory( new CategoryFetchOneSummary( categoryId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Category using Id " + categoryId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Category business objects
     * @return		Set<Category>
     */
    @GetMapping("/")
    public List<Category> loadAll() {                
    	List<Category> categoryList = null;
        
    	try {
            // load the Category
            categoryList = service.getAllCategory();
            
            if ( categoryList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Categorys" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Categorys ", exc );
        	return null;
        }

        return categoryList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Category category = null;
    protected CategoryService service = null;
    private static final Logger LOGGER = Logger.getLogger(CategoryQueryRestController.class.getName());
    
}
